// thumbnail-generator.js
const puppeteer = require('puppeteer');
const sharp = require('sharp');

async function generateThumbnailFromHtml({html, targetW=200, targetH=260, paddingPct=0.06, dpr=2, background='#ffffff'}) {
  const browser = await puppeteer.launch({args: ['--no-sandbox']});
  const page = await browser.newPage();

  // Render at a large viewport to capture full fidelity
  const viewportWidth = Math.round(targetW * dpr * 4); // capture plenty of pixels
  const viewportHeight = Math.round(targetH * dpr * 4);
  await page.setViewport({width: viewportWidth, height: viewportHeight, deviceScaleFactor: 1});

  // Load HTML; ensure body background matches "background" for transparent templates
  await page.setContent(`
    <style>
      html,body,#root{ margin:0; padding:0; background:${background}; height:100%; width:100%; }
      /* ensure template sits centered and not transformed */
      #root { display:flex; align-items:center; justify-content:center; }
    </style>
    <div id="root">${html}</div>
  `, {waitUntil: 'networkidle0'});

  // compute bounding box of #root's child (the template)
  const bbox = await page.evaluate(() => {
    const el = document.querySelector('#root').firstElementChild || document.querySelector('#root');
    const r = el.getBoundingClientRect();
    return {x: r.x, y: r.y, width: r.width, height: r.height};
  });

  // screenshot of that bounding box at full resolution
  const clip = {
    x: Math.max(0, Math.floor(bbox.x)),
    y: Math.max(0, Math.floor(bbox.y)),
    width: Math.max(1, Math.ceil(bbox.width)),
    height: Math.max(1, Math.ceil(bbox.height))
  };

  const screenshotBuffer = await page.screenshot({clip, omitBackground: false, type: 'png'});
  await browser.close();

  // Now use sharp to resize using 'contain' and add padding
  const padPx = Math.round(Math.min(targetW, targetH) * paddingPct * dpr); // apply in DPR space
  const outW = targetW * dpr;
  const outH = targetH * dpr;

  const result = await sharp(screenshotBuffer)
    .resize(outW - padPx*2, outH - padPx*2, { fit: 'contain', background: background })
    .extend({
      top: padPx,
      bottom: padPx,
      left: padPx,
      right: padPx,
      background: background
    })
    .resize(outW, outH) // final ensure exact dims
    .webp({quality: 75})
    .toBuffer();

  return result; // use to upload and serve
}

